#!/bin/bash
# generate.sh CONFIG SPEC SUITE: prints the tests generated by gen.sh, or an
# empty suite if they can't be generated on this host, e.g., without clang,
# lld, llvm-mc or QEMU.
dir=$(cd "$(dirname "$0")" && pwd)
if out=$(bash "$dir/gen.sh" "$@"); then
  printf '%s\n' "$out"
else
  echo "warning: the $3 tests are not generated, the suite is empty" >&2
  printf 'let suite = OUnit2.( >::: ) "%s" []\n' "$3"
fi
